/**
 * The third-party notices match package-lock.json. THIRD_PARTY.md, NOTICE.md, CREDITS.md
 * and public/licenses.txt are generated by scripts/third-party.mjs; after a dependency
 * change, `npm run licenses` brings them up to date, and this suite fails until it has.
 */
import { describe, it, expect } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';
import { basename } from 'node:path';
import { closure, collect, outputs, resolveLocation } from '../../scripts/third-party.mjs';

const data = collect();

describe('third-party notices', () => {
  it.each(outputs(data).map(([file, text]) => [basename(file), file, text]))(
    '%s is up to date (npm run licenses)',
    (_name, file, text) => {
      expect(existsSync(file)).toBe(true);
      expect(readFileSync(file, 'utf8').replace(/\r\n/g, '\n')).toBe(text);
    },
  );

  it('lists the runtime dependencies and what they bring in', () => {
    const names = data.shipped.map((pkg) => pkg.name);
    for (const name of ['three', '@iwsdk/core', '@companionintelligence/tokens', '@companionintelligence/fonts']) {
      expect(names).toContain(name);
    }
    expect(names).not.toContain('vite');
    expect(names).not.toContain('wrangler');
  });

  it('knows the licence of everything that ships, and finds no copyleft', () => {
    for (const pkg of data.thirdParty) {
      expect(pkg.license, pkg.name).toMatch(/^(MIT|Apache-2\.0|BSD-[23]-Clause|ISC|OFL-1\.1|0BSD)( (AND|OR) (MIT|Apache-2\.0|BSD-[23]-Clause|ISC|OFL-1\.1|0BSD))*$/);
    }
  });

  it('ships a licence text for every third-party package', () => {
    const text = outputs(data).find(([file]) => file.endsWith('licenses.txt'))[1];
    for (const pkg of data.thirdParty) {
      expect(text, pkg.name).toContain(`\n${pkg.name} ${pkg.version}\n`);
    }
    expect(text).toContain('Required Notice: Copyright LifeScope INC, DBA Companion Intelligence (https://ci.computer)');
    expect(text).toContain('This Font Software is licensed under the SIL Open Font License, Version 1.1.');
  });
});

describe('lockfile resolution', () => {
  const packages = {
    '': {},
    'node_modules/a': { version: '1.0.0', dependencies: { b: '^1', c: '^2' } },
    'node_modules/a/node_modules/b': { version: '1.5.0', peerDependencies: { d: '*', e: '*' }, peerDependenciesMeta: { e: { optional: true } } },
    'node_modules/b': { version: '2.0.0' },
    'node_modules/c': { version: '2.1.0', optionalDependencies: { gone: '*' } },
    'node_modules/d': { version: '3.0.0' },
    'node_modules/e': { version: '4.0.0' },
  };

  it('prefers the nested copy, then walks up to the root', () => {
    expect(resolveLocation(packages, 'node_modules/a', 'b')).toBe('node_modules/a/node_modules/b');
    expect(resolveLocation(packages, 'node_modules/a/node_modules/b', 'd')).toBe('node_modules/d');
    expect(resolveLocation(packages, '', 'missing')).toBeNull();
  });

  it('follows dependencies and required peers, and skips optional peers and absent optional dependencies', () => {
    const found = closure({ packages }, ['a']).map((pkg) => `${pkg.name}@${pkg.version}`).sort();
    expect(found).toEqual(['a@1.0.0', 'b@1.5.0', 'c@2.1.0', 'd@3.0.0']);
  });
});
